import {calculate,plans,rankPlans,coverage,bonusCurve,bonusTax,cashKeys,VERSION,total,lawfulKeys,lawfulTotal} from './engine.mjs';
import {TYPES,deductionTotals,deductionValue} from './deductions.mjs';
export const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
export const money=n=>n===null||n===undefined?'—':(n/100).toLocaleString('zh-CN',{minimumFractionDigits:2,maximumFractionDigits:2});
export const yuan=n=>n===null||n===undefined?'待补齐':'¥ '+money(n);
export const names={salary:'基本工资',bonus:'普通月度奖金',overtime:'加班费',allowance:'应税补贴及其他收入',reduction:'税前工资扣减',pension:'个人养老保险',medical:'个人医疗保险',unemployment:'个人失业保险',socialOther:'其他个人社保',fund:'个人住房公积金',fundExtra:'补充公积金（合规可扣部分）',otherDeduct:'其他依法扣除（不含台账及养老金）',after:'其他税后扣款',reimburse:'非应税报销／到账增加',pensionPay:'个人养老金实际缴费'};
export const labels={missing:'未填写',forecast:'预测',actual:'已发生'};
export const lawfulTypes={
  annuity:{name:'企业年金／职业年金个人缴费',help:'仅填写符合规定的个人缴费可扣部分；通常不超过本人缴费工资计税基数的4%。'},
  health:{name:'符合规定的商业健康保险',help:'须为符合税收优惠规定的产品；每月最多200元，全年最多2400元。'},
  taxDeferredPension:{name:'税收递延型商业养老保险',help:'仅填写符合原试点及衔接政策、可在当前申报中扣除的金额；不要重复填写个人养老金。'},
  other:{name:'其他有明确政策依据的扣除',help:'仅在有国务院或主管部门明确依据、凭证且未在其他项目申报时填写。'}
};
export const tabs=[['overview','◫','收入总览'],['monthly','▤','月度精算'],['quick','◷','年度快算'],['annual','▥','年度记录'],['deductions','▧','扣除台账'],['planning','◇','个税筹划'],['settings','⚙','设置与备份']];
const row=(a,b)=>`<div class="fundrow"><span>${a}</span><b>${b}</b></div>`;
const tag=(x,warn=false)=>`<span class="tag ${warn?'warn':''}">${x}</span>`;
const panel=(title,body,side='')=>`<section class="panel"><div class="panelhead"><h2>${title}</h2>${side}</div>${body}</section>`;
const check=(id,label,checked=false)=>`<label class="check"><input id="${id}" name="${id}" type="checkbox" ${checked?'checked':''}>${label}</label>`;
export function field(k,label,value,help='',type='number'){
  return `<div class="field"><label for="${k}">${label}${type==='number'?' / 元':''}</label><input id="${k}" name="${k}" type="${type}" ${type==='number'?'min="0" max="100000000" step="0.01"':'maxlength="40"'} value="${type==='number'?(value/100).toFixed(2):esc(value)}" required>${help?`<small>${help}</small>`:''}</div>`;
}
function select(id,label,values,current){return `<div class="field"><label for="${id}">${label}</label><select id="${id}" name="${id}">${values.map(([v,n])=>`<option value="${esc(v)}" ${String(current)===String(v)?'selected':''}>${n}</option>`).join('')}</select></div>`;}
function optionalMoneyField(id,label,value,help=''){return `<div class="field"><label for="${id}">${label} / 元</label><input id="${id}" name="${id}" type="number" min="0" max="100000000" step="0.01" value="${value===null?'':(value/100).toFixed(2)}" placeholder="留空默认按基本工资"><small>${help}</small></div>`;}
function percentField(id,label,value){return `<div class="field suffix-field"><label for="${id}">${label}</label><div><input id="${id}" name="${id}" type="number" min="0" max="100" step="0.01" value="${(value/100).toFixed(2)}" required><span>%</span></div></div>`;}
function lawfulFields(prefix,values,annual=false){
  return `<div class="lawful-grid">${lawfulKeys.map(key=>{const meta=lawfulTypes[key],id=`${prefix}law_${key}`,enabled=(values?.[key]??0)>0;return `<div class="lawful-item ${enabled?'selected':''}"><label class="lawful-check"><input name="${prefix}law_enabled_${key}" type="checkbox" data-law-toggle="${id}" ${enabled?'checked':''}><span><b>${meta.name}</b><small>${meta.help}</small></span></label><div class="field"><label for="${id}">${annual?'全年':'本月'}可扣金额 / 元</label><input id="${id}" name="${id}" type="number" min="0" max="100000000" step="0.01" value="${((values?.[key]??0)/100).toFixed(2)}" ${enabled?'':'disabled'} required></div></div>`;}).join('')}</div>`;
}
function flowSteps(step,canResult,label){return `<div class="flow-head"><div><span class="eyebrow">当前测算</span><b>${label}</b></div><div class="flow-steps"><button type="button" data-flow-step="1" class="${step===1?'active':''}"><i>1</i>填写金额与扣除</button><span></span><button type="button" data-flow-step="2" class="${step===2?'active':''}" ${canResult?'':'disabled'}><i>2</i>查看计算结果</button></div></div>`;}
function card(label,value,note,dark=false){return `<div class="card ${dark?'dark':''}"><div class="label">${label}</div><div class="big">${label==='待确认项目数'?value/100+' 项':yuan(value)}</div><div class="note">${note}</div></div>`;}
function warning(s){
  const c=coverage(s),warnings=[];
  if(s.mode==='monthly'&&c.missing.length)warnings.push(`未填月份：${c.missing.join('、')}月`);
  if(s.mode==='quick'&&!s.quick.confirmed)warnings.push('年度快算尚未保存并确认');
  if(c.pendingBaseline)warnings.push(`${c.pendingBaseline}项基准扣除待分类或确认`);
  if(!s.scope)warnings.push('尚未确认产品适用范围');
  if(!warnings.length)return '';
  return `<div class="banner"><div><b>暂不生成全年推荐</b><br>${warnings.join('；')}。缺失数据不按0计算。</div><button data-tab="${c.pendingBaseline?'deductions':!s.scope?'settings':s.mode==='quick'?'quick':'monthly'}">去补齐</button></div>`;
}
function footer(){return `<footer class="footer"><span>中国内地居民 · 自年初同一单位普通工资场景。测算仅供参考，实际以适用政策及扣缴申报为准。</span><span>数据仅存本机 · ${VERSION}</span></footer>`;}
export function page(s,tab,editDed=null,flowStep=1){
  const r=calculate(s),titles={overview:'看清收入，从容规划',monthly:'每一笔到手，都有明细',quick:'先看全年，再补细节',annual:'把一整年的收入放在一起',deductions:'每项扣除，都有依据',planning:'比较方案，再做选择',settings:'你的数据，由你掌握'};
  const content=tab==='monthly'?monthly(s,r,flowStep):tab==='quick'?quick(s,r,flowStep):tab==='deductions'?deductions(s,r,editDed):({overview,annual,planning,settings}[tab])(s,r);
  return `<div class="layout"><aside class="sidebar"><div class="brand"><div class="brandicon">≈</div><div><strong>薪有数</strong><small>INCOME, IN PERSPECTIVE</small></div></div><nav class="nav">${tabs.map(([id,i,n])=>`<button data-tab="${id}" class="${tab===id?'active':''}"><span>${i}</span>${n}</button>`).join('')}</nav><div class="sidefoot"><div class="privacy">◉ 数据仅保存在本机</div>让收入清楚一点<br>让规划从容一点<br><br>个人收入规划工具 / V3.0</div></aside><main><header class="topbar"><span class="crumb">个人工作台 / ${tabs.find(t=>t[0]===tab)[2]}</span><div class="topright"><select id="year" aria-label="纳税年度"><option ${s.year===2026?'selected':''}>2026</option><option ${s.year===2027?'selected':''}>2027</option></select>${tag(s.demo?'示例模式':'本机记录')}</div></header>${s.demo?`<div class="banner"><span>以下为示例情景，不代表你的收入。开始测算会建立空白年度。</span><button data-action="start">开始我的测算</button></div>`:''}${s.migrationNotice?`<div class="banner"><span>旧版记录已升级保留；原“其他依法扣除”暂归入其他项目，请核对分类和凭证。</span><button data-action="oldBackup">下载旧版快照</button></div>`:''}<div class="heading"><div><h1>${titles[tab]}</h1><p class="sub">${s.year}年度 · ${s.mode==='quick'?'年度快算（不推算月度到账）':'月度精算（实际与预测分别记录）'}</p></div><div class="actions"><button data-mode="monthly" class="${s.mode==='monthly'?'primary':''}">月度精算</button><button data-mode="quick" class="${s.mode==='quick'?'primary':''}">年度快算</button></div></div>${warning(s)}${content}${footer()}</main></div>`;
}
function overview(s,r){
  const quick=s.mode==='quick';
  const cards=`<div class="cards">${card(r.complete?'全年税前收入':'已录收入＋奖金',r.gross,r.complete?'含全年一次性奖金':'部分数据，不代表全年',true)}${card('全年最终个税',r.finalTax,r.complete?'基准方案 · 含预测':'数据不齐，不输出税额')}${card('全年可支配现金',r.disposable,'按全年最终税负，扣除个人缴费')}${card('个人社保及公积金',r.cash,quick?'年度输入合计':'已填月份个人缴费合计')}</div>`;
  const chart=quick?`<div class="empty">年度总额不能准确推算月度到账。<br>如需每月趋势，请切换月度精算并逐月录入。</div>`:monthlyChart(s,r);
  const c=coverage(s);
  return `${cards}<div class="grid">${panel('全年到手趋势',chart,tag(quick?'年度快算':'基准方案'))}${panel('数据与税款状态',`${row('已发生 / 预测 / 未填',s.mode==='quick'?'年度模式':`${s.months.filter(m=>m.status==='actual').length} / ${s.months.filter(m=>m.status==='forecast').length} / ${c.missing.length}`)}${row('全年预计预缴税款',quick?'不推算':yuan(r.paid))}${row('预计汇算差额',quick?'不推算':r.settlement===null?'待补齐':`${r.settlement>=0?'应补':'应退'} ${yuan(Math.abs(r.settlement))}`)}${row('基准专项附加扣除',yuan(r.special))}<div class="helper">${quick?'年度快算与月度数据独立保存，共用奖金与扣除台账。':'“已发生”但未填实际税额的月份仍使用预测税额，不能视为已核验扣缴。'}</div>`)}</div><div class="grid">${panel('从哪里开始？',`<p class="sub">想快速比较奖金方式，先录年度总额；想核对工资条，按月填收入与个人扣缴。</p><div class="actions" style="margin-top:20px"><button data-tab="quick">年度快速录入</button><button data-tab="monthly">逐月核对</button></div>`)}${panel('下一步：比较可执行方案',`<p class="sub">在完整数据下比较奖金计税、补充扣除及养老金的全部可用组合。</p><div class="actions" style="margin-top:20px"><button class="primary" data-tab="planning">查看方案与理由 →</button><button data-tab="deductions">核对扣除台账</button></div>`)}</div>`;
}
function monthlyChart(s,r){
  const max=Math.max(1,...r.rows.map(v=>v.take??0));
  return `<div class="chart">${r.rows.map((v,i)=>`<div class="barcol ${s.selected===i?'current':''}"><div class="bartrack"><div class="bar ${v.valid?'':'missingbar'}" title="${i+1}月 ${v.valid?yuan(v.take):'数据不齐'}" style="height:${v.valid?Math.max(1,(v.take??0)/max*100):4}%"></div></div><span>${i+1}月</span></div>`).join('')}</div><div class="legend"><span><i class="dot"></i>当前查看月份</span><span><i class="dot light"></i>含预测</span><span>空缺后累计结果暂停</span></div>`;
}
function contributionEditor(m){
  return `<h3 class="sectiontitle">个人社保与公积金</h3><p class="sub">比例已填入常用个人缴费默认值，可按当地政策和工资条修改。缴费基数留空时自动使用基本工资。</p><div class="formgrid" style="margin-top:18px">${optionalMoneyField('socialBase','社保缴费基数',m.socialBase,'留空时跟随本月基本工资；当地上下限需自行核对。')}${percentField('pensionRate','养老保险个人比例',m.pensionRate)}${percentField('medicalRate','医疗保险个人比例',m.medicalRate)}${percentField('unemploymentRate','失业保险个人比例',m.unemploymentRate)}${percentField('maternityRate','生育保险个人比例',m.maternityRate)}${percentField('injuryRate','工伤保险个人比例',m.injuryRate)}</div><div class="contribution-preview"><div><span>养老保险</span><b data-contribution-output="pension">${yuan(m.pension)}</b></div><div><span>医疗保险</span><b data-contribution-output="medical">${yuan(m.medical)}</b></div><div><span>失业保险</span><b data-contribution-output="unemployment">${yuan(m.unemployment)}</b></div><div><span>生育及工伤</span><b data-contribution-output="socialOther">${yuan(m.socialOther)}</b></div></div><div class="fund-config"><label class="switch-row"><input id="fundEnabled" name="fundEnabled" type="checkbox" ${m.fundEnabled?'checked':''}><span><b>缴纳住房公积金</b><small>关闭后本月个人住房公积金按0计算</small></span></label><div class="formgrid">${optionalMoneyField('fundBase','公积金缴费基数',m.fundBase,'留空时跟随本月基本工资。')}${percentField('fundRate','公积金个人比例',m.fundRate)}${field('fundExtra',names.fundExtra,m.fundExtra,'只填符合税前扣除范围的个人实际缴费。')}</div><div class="contribution-preview single"><div><span>住房公积金</span><b data-contribution-output="fund">${yuan(m.fund)}</b></div></div></div>`;
}
function monthly(s,r,step=1){
  const m=s.months[s.selected],v=r.rows[s.selected],d=deductionTotals(s.deductions),canResult=m.status!=='missing';
  const nav=`<div class="monthnav" aria-label="选择月份">${s.months.map((item,i)=>`<button data-month="${i}" class="${s.selected===i?'active':''}" title="${labels[item.status]}">${i+1}月${item.status==='missing'?' ·':''}</button>`).join('')}</div>`;
  const head=flowSteps(step,canResult,`${s.selected+1}月 · ${labels[m.status]}`);
  if(step===2&&canResult){
    const result=`<section class="panel result-page"><div class="result-hero"><div><span class="tag">${s.selected+1}月 · ${labels[m.status]}</span><div class="label">预计到手金额</div><div class="big">${yuan(v.take)}</div></div><button type="button" data-flow-step="1">← 返回修改</button></div><div class="result-columns"><div>${row('应税工资收入',yuan(v.gross))}${row('当月全年一次性奖金',yuan(v.bp))}${row('社保与公积金',yuan(v.cash))}${row('其他依法扣除',yuan(m.otherDeduct))}</div><div>${row('普通工资个税',yuan(v.tax))}${v.bonusTax?row('奖金单独计税税款',yuan(v.bonusTax)):''}${row('实际已录普通工资税款',m.status==='actual'?yuan(m.actualTax):'未发生')}${row('税后扣款＋养老金',yuan(m.after+m.pensionPay))}${row('报销／到账增加',yuan(m.reimburse))}</div></div>${v.valid?`<details open><summary>累计计税过程</summary><div class="result-columns"><div>${row('累计计税收入',yuan(v.inc))}${row('累计减除费用',yuan((s.selected+1)*500000))}${row('累计其他扣除及缴费',yuan(v.ded+v.pensionDed))}</div><div>${row('累计应纳税所得额',yuan(v.detail.base))}${row('税率 / 速算扣除',`${v.detail.rate}% / ${yuan(v.detail.quick)}`)}${row('累计应预扣税额',yuan(v.detail.amount))}${row('累计普通工资已扣税',yuan(v.cumulativeTax))}</div></div></details>`:'<div class="helper">本月或此前月份未填，或基准扣除待确认；暂停累计个税及到手计算。</div>'}${v.take!==null&&v.take<0?'<div class="error">预计到账为负，请核对输入。</div>':''}</section>`;
    return `${nav}${head}${result}<div style="margin-top:22px">${fundTable(s,r)}</div>`;
  }
  return `${nav}${head}<section class="panel flow-form"><div class="panelhead"><h2>${s.selected+1}月金额与扣除项目</h2>${tag(labels[m.status],m.status==='missing')}</div><form id="monthForm"><h3>收入信息</h3><div class="formgrid">${select('status','保存为',[['forecast','预测收入（0也表示已确认）'],['actual','已发生收入']],m.status==='missing'?'forecast':m.status)}${['salary','bonus','overtime','allowance','reduction'].map(k=>field(k,names[k],m[k])).join('')}</div>${contributionEditor(m)}<h3 class="sectiontitle">其他依法确定的扣除（可多选）</h3><p class="sub">按项目分别填写计税可扣金额；不要重复填写社保、公积金、专项附加扣除或个人养老金。若该笔支出还会减少工资到账，请同时在下方“其他税后扣款”记录实际现金影响。</p>${lawfulFields('',m.lawfulDeductions)}<h3 class="sectiontitle">专项附加扣除与到账调整</h3><div class="helper">本月台账预扣扣除：${yuan(d.monthly[s.selected])}。<button type="button" class="miniLink" data-tab="deductions">到台账维护</button> 专项附加扣除不再另填合计，避免重复。</div><div class="formgrid" style="margin-top:18px">${['pensionPay','after','reimburse'].map(k=>field(k,names[k],m[k],k==='pensionPay'?'按缴费当月在预扣环节享受模拟，年度上限12000元；不适用此口径时请使用年度快算。':'')).join('')}<div class="field"><label for="actualTax">实际工资条个税 / 元</label><input id="actualTax" name="actualTax" type="number" min="0" max="100000000" step="0.01" value="${m.actualTax===null?'':(m.actualTax/100).toFixed(2)}" placeholder="选填，留空使用预测"><small>只在已发生状态使用；仅填普通工资综合所得预扣税，不含单独计税奖金税款。</small></div></div><div class="submit-zone"><div><b>提交前会再次确认</b><span>确认后保存本月数据，并进入计算结果页。</span></div><div class="actions"><button class="primary" type="submit">确认并查看结果 →</button><button type="button" data-action="copy">复制到后续月份</button><button type="button" data-action="markMissing">标为未填写</button></div></div><p class="sub">保存全部0金额，表示确认该月0收入；未点击保存仍是未填写。复制不会覆盖已发生月份。</p></form></section>`;
}
function fundTable(s,r){
  const i=s.selected,keys=[...cashKeys,'tax','bonusTax','after','pensionPay'];
  const get=(j,k)=>s.months[j].status==='missing'?null:k==='tax'||k==='bonusTax'?r.rows[j].valid?r.rows[j][k]:null:s.months[j][k];
  const cum=k=>{const vs=Array.from({length:i+1},(_,j)=>get(j,k));return vs.includes(null)?null:total(vs);};
  const sumOrNull=vs=>vs.includes(null)?null:total(vs);
  return panel(`${i+1}月扣缴资金去向`,`<div class="tablewrap"><table><thead><tr><th>扣缴项目</th><th>当月金额</th><th>截至${i+1}月累计</th></tr></thead><tbody>${keys.map(k=>`<tr><td>${k==='tax'?'普通工资个人所得税':k==='bonusTax'?'单独计税奖金税款':names[k]}</td><td>${money(get(i,k))}</td><td>${money(cum(k))}</td></tr>`).join('')}<tr><td><b>个人扣缴及缴费总额</b></td><td>${money(sumOrNull(keys.map(k=>get(i,k))))}</td><td>${money(sumOrNull(keys.map(cum)))}</td></tr></tbody></table></div><p class="sub">累计含预测。个人养老金为个人账户缴费，不代表单位代扣。缺失数据用“—”展示，不按0累计。</p>`);
}
function quick(s,r,step=1){
  const q=s.quick,d=deductionTotals(s.deductions),canResult=q.confirmed,quickNames={salary:'全年工资（不含全年一次性奖金）',cash:'全年个人社保及公积金',pensionPay:'本年个人养老金已有缴费',after:'全年其他税后扣款',reimburse:'全年非应税报销及到账增加'};
  const head=flowSteps(step,canResult,`${s.year}年度快算`);
  if(step===2&&canResult){
    const lawfulRows=lawfulKeys.filter(k=>q.lawfulDeductions[k]>0).map(k=>row(lawfulTypes[k].name,yuan(q.lawfulDeductions[k]))).join('')||row('其他依法扣除','¥ 0.00');
    return `${head}<section class="panel result-page"><div class="result-hero"><div><span class="tag">${s.year}年度 · 已确认</span><div class="label">全年可支配现金</div><div class="big">${yuan(r.disposable)}</div></div><button type="button" data-flow-step="1">← 返回修改</button></div><div class="result-columns"><div>${row('工资及全年一次性奖金',yuan(r.gross))}${row('个人社保及公积金',yuan(r.cash))}${row('专项附加扣除',yuan(r.special))}${row('个人养老金已有缴费',yuan(r.pensionActual))}</div><div>${row('全年最终个税',yuan(r.finalTax))}${row('其他依法扣除合计',yuan(r.other))}${row('全年其他税后扣款',yuan(q.after))}${row('全年到账增加',yuan(q.reimburse))}</div></div><details open><summary>其他依法扣除明细</summary>${lawfulRows}</details><div class="actions" style="margin-top:22px"><button class="primary" data-tab="planning">继续比较个税方案 →</button><button data-tab="annual">查看年度记录</button></div><div class="helper">年度快算不推算每月到账、预缴税额或退补税；结果按当前已确认年度总额计算。</div></section>`;
  }
  return `${head}${panel('第一页：填写年度金额与扣除项目',`<div class="intro">这里的输入独立保存，不覆盖月度记录，也不会平均分摊为月工资。奖金和专项附加扣除台账为年度共用信息。</div><form id="quickForm"><h3>年度金额</h3><div class="formgrid">${Object.keys(quickNames).map(k=>field('q_'+k,quickNames[k],q[k])).join('')}</div><h3 class="sectiontitle">其他依法确定的扣除（可多选）</h3><p class="sub">按项目填写全年可扣金额，商业健康保险全年不超过2400元。</p>${lawfulFields('q_',q.lawfulDeductions,true)}<div class="helper">全年一次性奖金：${yuan(s.bonus)} <button type="button" class="miniLink" data-tab="planning">修改</button><br>已确认基准专项附加扣除：${yuan(d.baseline)} <button type="button" class="miniLink" data-tab="deductions">查看台账</button></div>${check('quickConfirmed','我已核对全年输入，包括实际收入和未来预测；填写0的项目已确认无金额。',q.confirmed)}<div class="submit-zone"><div><b>提交前会再次确认</b><span>确认后保存年度数据，并进入计算结果页。</span></div><button class="primary" type="submit">确认并查看结果 →</button></div></form><div class="helper">年度快算只输出年度最终税款和可支配现金，不推算每月到账、预缴税额或退补税。</div>`)}`;
}
function annual(s,r){
  if(s.mode==='quick')return panel('年度快算记录',`${row('工资及全年一次性奖金',yuan(r.gross))}${row('个人社保及公积金',yuan(r.cash))}${row('其他依法扣除',yuan(r.other))}${row('全年最终个税',yuan(r.finalTax))}${row('全年可支配现金',yuan(r.disposable))}<div class="actions" style="margin-top:18px"><button data-tab="quick">返回年度快算流程</button><button data-tab="planning" class="primary">比较方案</button></div>`);
  return panel('十二个月，逐笔可查',`<div class="actions" style="margin-bottom:18px"><button data-action="csv">↓ 导出月度及累计扣缴明细</button></div><div class="tablewrap"><table><thead><tr><th>月份</th><th>状态</th><th>工资及奖金</th><th>个人缴费</th><th>普通工资个税</th><th>奖金单独税</th><th>累计普通工资税</th><th>预计到手</th></tr></thead><tbody>${r.rows.map((v,i)=>`<tr><td><button class="miniLink" data-month="${i}">${i+1}月 ↗</button></td><td>${tag(labels[s.months[i].status],s.months[i].status!=='actual')}</td><td>${s.months[i].status==='missing'?'—':money(v.gross+v.bp)}</td><td>${s.months[i].status==='missing'?'—':money(v.cash)}</td><td>${money(v.tax)}${s.months[i].status==='actual'&&s.months[i].actualTax===null?'<small>（预测）</small>':''}</td><td>${v.valid?money(v.bonusTax):'—'}</td><td>${money(v.cumulativeTax)}</td><td><b>${money(v.take)}</b></td></tr>`).join('')}</tbody></table></div><div class="helper">基准奖金方式：${s.currentBonusMode==='combined'?'并入综合所得':'单独计税'}。已发生但未填实际工资税款的月份，仍使用系统预测。缺失月份及其后累计税额不输出。</div>`);
}
function deductions(s,r,edit){
  const d=deductionTotals(s.deductions);
  const table=panel('年度扣除台账',`<div class="cards compact">${card('已确认基准扣除',d.baseline,'计入当前基准')}${card('已确认新增扣除',d.proposed,'仅在备选组合中使用')}${card('待确认项目数',(d.pendingBaseline+d.pendingProposed)*100,'不进入正式计算')}</div><div class="actions" style="margin-bottom:18px"><button class="primary" data-action="addDed">＋ 新增扣除项目</button></div>${s.deductions.length?`<div class="tablewrap"><table><thead><tr><th>项目 / 对象</th><th>月份</th><th>年度可用金额</th><th>用途</th><th>环节</th><th>状态</th><th>操作</th></tr></thead><tbody>${s.deductions.map(x=>`<tr><td>${TYPES[x.type].name}<br><span class="muted">${esc(x.person)}</span></td><td>${TYPES[x.type].annual?'年度':x.start+'—'+x.end+'月'}</td><td>${x.confirmed?money(deductionValue(x)):'待确认'}${x.type==='legacy'?`<br><small>原金额 ${money(x.amount)}${x.timing==='withholding'?'/月':'/年'}</small>`:''}</td><td>${x.usage==='baseline'?'基准已有':'备选新增'}</td><td>${x.timing==='annual'?'仅年度汇算':'工资预扣＋年度'}</td><td>${tag(x.confirmed?'已确认':'待确认',!x.confirmed)}</td><td><button class="miniLink" data-edit-ded="${esc(x.id)}">编辑</button> <button class="miniLink" data-delete-ded="${esc(x.id)}">删除</button></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty">暂无项目。若确实没有可用扣除，可保持空台账；无需填0项目。</div>'}<div class="helper">台账记录的是个人可扣金额，不是实际现金支出。未确认基准扣除会暂停全年结果；未确认备选只提示，不参加比较。住房互斥、重叠月份和额度由系统检查，真实资格仍需你核对。</div>`);
  return `${table}${edit?`<div style="margin-top:22px">${dedEditor(edit)}</div>`:''}${policyPanel()}`;
}
function dedEditor(d){
  const meta=TYPES[d.type],monthOpts=Array.from({length:12},(_,i)=>[i+1,`${i+1}月`]);
  return panel('编辑扣除项目',`<form id="dedForm" data-id="${esc(d.id)}"><div class="formgrid">${select('d_type','扣除项目',Object.entries(TYPES).filter(([k])=>k!=='legacy'||d.type==='legacy').map(([k,v])=>[k,v.name]),d.type)}${field('d_person',meta.person?'对象标记（如孩子A，无需实名）':'对象标记',d.person,'同一对象保持相同标记，便于检查重复。','text')}${select('d_usage','计入方案',[['baseline','基准已有扣除'],['proposed','备选新增扣除']],d.usage)}${select('d_timing','使用环节',(meta.annual||d.usage==='proposed')?[['annual','仅年度汇算']]:[['withholding','工资预扣＋年度汇算'],['annual','仅年度汇算']],d.timing)}${!meta.annual?select('d_start','适用起始月份',monthOpts,d.start)+select('d_end','适用结束月份',monthOpts,d.end):''}${field('d_amount',d.type==='medical'?'该对象年度医保目录内自付额':meta.annual?'个人年度可扣金额':'个人每月可扣金额',d.amount)}${['child','baby','loan'].includes(d.type)?select('d_share','个人分配比例',[[100,'100%'],[50,'50%']],d.share):''}${d.type==='rent'?select('d_rentTier','主要工作城市扣除档',[[150000,'1500元/月'],[110000,'1100元/月'],[80000,'800元/月']],d.rentTier):''}${d.type==='elder'?select('d_sole','是否独生子女',[['yes','是：每月最高3000元'],['no','否：每月最高1500元']],d.sole?'yes':'no'):''}</div><div class="helper">${meta.help}${d.usage==='proposed'?'<br>备选新增扣除统一按年度汇算模拟，不修改月度已扣税。':''}</div>${check('d_confirmed','我已核对项目资格、适用月份、分配及历史期限；个人金额未在其他项目、其他依法扣除或家庭成员重复申报。',d.confirmed)}${d.type==='legacy'?'<div class="error">请先选择具体扣除项目。若原合计含多项，请分别建项，完成后再移除旧合计。</div>':''}<div class="actions" style="margin-top:16px"><button class="primary" type="submit">保存项目并校验</button><button type="button" data-action="cancelDed">取消编辑</button></div></form>`);
}
function planning(s,r){
  const list=plans(s),ranked=rankPlans(list,s.goal),d=deductionTotals(s.deductions),best=ranked[0];
  const input=panel('设置比较条件',`<form id="planForm"><div class="formgrid">${field('annualBonus','全年一次性奖金',s.bonus,'不含已录入工资中的普通奖金；不拆分已发的一笔奖金。')}${select('bonusMonth','预计取得月份',Array.from({length:12},(_,i)=>[i+1,`${i+1}月`]),s.bonusMonth)}${field('pensionPlan','计划新增养老金预算',s.pensionPlan,'最高12000元；扣除已有缴费后，按剩余额度计算。')}${select('currentBonusMode','当前基准计税方式',s.bonusEligible?[['combined','并入综合所得'],['separate','单独计税']]:[['combined','并入综合所得']],s.currentBonusMode)}${select('goal','比较目标',[['cash','全年可支配现金较高'],['tax','全年最终税款较低']],s.goal)}</div>${check('bonusEligible','我确认该笔奖金符合全年一次性奖金条件，当年未对其他奖金使用单独计税，取得年度在有效期内。',s.bonusEligible)}<div class="helper">基准扣除 ${yuan(d.baseline)}；备选新增扣除 ${yuan(d.proposed)}；待确认备选 ${d.pendingProposed}项（不计入比较）。<button type="button" class="miniLink" data-tab="deductions">维护扣除台账</button></div><button class="primary" type="submit" style="margin-top:16px">更新方案比较</button></form>`);
  const result=!best?panel('方案比较尚未就绪','<div class="empty">补齐年度数据、确认基准扣除及适用范围后，再比较可用方案。</div>'):recommendation(s,list,ranked);
  return `<div class="stack">${input}${result}${cliffPanel(s,r)}${policyPanel()}</div>`;
}
function recommendation(s,list,ranked){
  const best=ranked[0],byTax=rankPlans(list,'tax')[0],byCash=rankPlans(list,'cash')[0];
  const tied=ranked.filter(x=>s.goal==='tax'?x.finalTax===best.finalTax:x.disposable===best.disposable);
  const instruction=[best.mode!==s.currentBonusMode?'核对奖金资格并选择对应计税方式':'保留当前奖金计税方式',best.extra?'将台账中全部已确认“备选新增扣除”按条件纳入年度汇算':'不新增台账扣除',best.addedPension?`在已录缴费之外新增个人养老金 ${yuan(best.addedPension)}，确认资金安排及凭证`:'不新增养老金缴费'];
  return panel(s.demo?'示例情景比较（不作为个人推荐）':'当前条件下的比较结论',`<div class="intro"><h3>${best.name}</h3>当前目标：${s.goal==='tax'?'全年税款较低':'全年可支配现金较高'}。相比基准预计少缴税 <b>${yuan(best.saving)}</b>，可支配现金变化 <b>${best.cashChange>=0?'+':'−'}${yuan(Math.abs(best.cashChange))}</b>。${tied.length>1?`有${tied.length}个方案在当前目标上并列，优先展示改变事项较少、追加缴费较少的方案。`:''}</div><div class="checklist"><div class="checkitem"><b>税款最低</b>${esc(byTax.name)}<br>${yuan(byTax.finalTax)} / 年</div><div class="checkitem"><b>可支配现金最高</b>${esc(byCash.name)}<br>${yuan(byCash.disposable)} / 年</div></div><h3 class="sectiontitle">为什么选择它，执行前需要做什么？</h3><ol class="reasonList">${instruction.map(x=>`<li>${x}</li>`).join('')}</ol><p class="sub">已比较${list.length}个有效组合：奖金方式 × 是否使用全部已确认新增扣除 × 是否追加预算内养老金。预测收入、资格或金额改变，结论随之变化。</p><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>方案</th><th>最终个税</th><th>比基准少缴税</th><th>新增支出／受限资金</th><th>可支配现金</th><th>改动项数</th></tr></thead><tbody>${ranked.map(p=>`<tr class="${p.id===best.id?'selectedRow':''}"><td>${esc(p.name)} ${p.id==='base'?tag('当前基准'):''}</td><td>${money(p.finalTax)}</td><td>${money(p.saving)}</td><td>${money(p.addedPension)}</td><td><b>${money(p.disposable)}</b></td><td>${p.changes}</td></tr>`).join('')}</tbody></table></div><details><summary>展开较优方案计算明细</summary>${row('全年收入',yuan(best.gross))}${row('个人社保及公积金',yuan(best.cash))}${row('基准专项附加扣除',yuan(best.special))}${row('本方案新增专项附加扣除',yuan(best.extra))}${row('其他依法扣除',yuan(best.other))}${row('养老金已有＋新增缴费',yuan(best.pensionActual+best.addedPension))}${row('年度综合所得应纳税所得额',yuan(best.annual.base))}${row('综合所得税款',yuan(best.annual.amount))}${row('奖金单独计税税款',yuan(best.bonusTax))}</details><div class="helper">只在当前输入和支持的组合中比较，不代表全部筹划方式的全局最优。养老金新增支出与新增受限资金是同一笔款，只扣一次；未预测未来收益及领取税款。普通收入同年调整发放月份，不视为年度节税。</div>`);
}
function cliffPanel(s,r){
  const curve=bonusCurve(s.bonus,r.annualIncomeBase),points=curve.points;
  const minY=Math.min(...points.map(p=>p.net),...(r.complete?points.map(p=>p.combined):[])),maxY=Math.max(...points.map(p=>p.net),...(r.complete?points.map(p=>p.combined):[]));
  const px=x=>55+(x-curve.min)/(curve.max-curve.min)*625,py=y=>205-(y-minY)/Math.max(1,maxY-minY)*175;
  const path=k=>points.map((p,i)=>`${i?'L':'M'}${px(p.amount).toFixed(2)},${py(p[k]).toFixed(2)}`).join(' ');
  const t=curve.nearest,delta=curve.plusOne.net-curve.at.net;
  return panel('奖金临界点 · 看税后变化',`<p class="sub">独立假设曲线，不是拆分建议。横轴为奖金税前金额，纵轴为该笔奖金带来的税后增加；绿色为单独计税，灰色为并入后的增量（需全年数据完整）。</p><svg class="taxcurve" viewBox="0 0 730 260" role="img" aria-label="奖金金额与税后奖金关系曲线"><path d="M55 25V215H690" fill="none" stroke="#dce5e7"/><path d="${path('net')}" fill="none" stroke="#187b69" stroke-width="3"/>${r.complete?`<path d="${path('combined')}" fill="none" stroke="#8a99a5" stroke-width="2" stroke-dasharray="6 4"/>`:''}<line x1="${px(t)}" y1="25" x2="${px(t)}" y2="215" stroke="#d39452" stroke-dasharray="4 4"/><circle cx="${px(s.bonus)}" cy="${py(curve.at.net)}" r="5" fill="#187b69"/><text x="55" y="240">${money(curve.min)}</text><text x="570" y="240">${money(curve.max)} 元奖金</text><text x="55" y="17">税后增加（元）</text><text x="${Math.min(540,Math.max(60,px(t)+8))}" y="38">临界 ${money(t)}</text></svg><div class="checklist"><div class="checkitem"><b>当前奖金 ${yuan(s.bonus)}</b>单独计税后 ${yuan(curve.at.net)}<br>奖金多1元，税后变化 <span class="${delta<0?'danger':'success'}">${delta<0?'−':'+'}${yuan(Math.abs(delta))}</span></div><div class="checkitem"><b>最近临界点 ${yuan(t)}</b>以下按临界点前后0.01元精确比较，不建议为卡档任意改变已发收入。</div></div><div class="tablewrap" style="margin-top:18px"><table><thead><tr><th>奖金税前金额</th><th>单独计税税额</th><th>单独计税后奖金</th></tr></thead><tbody>${[t-1,t,t+1,t+100].map(x=>`<tr><td>${money(x)}</td><td>${money(bonusTax(x))}</td><td>${money(x-bonusTax(x))}</td></tr>`).join('')}</tbody></table></div><div class="helper">${s.bonusEligible?'已确认单独计税资格。':'单独计税资格未确认，曲线仅演示公式，不加入推荐。'}${r.complete?'':' 年度数据未齐，暂停显示并入综合所得的税后增量曲线。'} 图形精度受像素限制，以0.01元边界表为准。政策有效期至2027年12月31日。</div>`);
}
function settings(s){return `<div class="stack">${panel('适用范围确认',`${check('scope','我是中国内地居民个人，本年度从1月起在同一单位任职；测算只涉及普通工资薪金及符合条件的全年一次性奖金，不含未支持收入或特殊预扣优惠。',s.scope)}<div class="helper">暂不支持换工作、多单位、劳务报酬、境外与经营所得、特殊预扣、减免税、低收入免办汇算判断。实际扣税与模型可能因这些原因不同。</div>`)}${panel('本机数据管理',`<p class="sub">记录仅保存在当前浏览器。年度快算与月度输入分别保存；奖金和扣除台账共用。切换不会覆盖另一种模式的数据。</p><div class="actions" style="margin-top:20px"><button class="primary" data-action="backup">↓ 导出完整备份</button><button data-action="import">↑ 导入备份</button><button data-action="csv">导出当前模式 CSV</button><button data-action="start">清空当前年度重新开始</button>${s.migrationNotice?'<button data-action="oldBackup">下载升级前快照</button>':''}</div><input type="file" id="importFile" accept="application/json,.json" hidden><div class="helper">导入会校验版本、金额和扣除冲突，确认后仅替换相同年度。旧版合计扣除需重新分类；原数据快照在迁移前保存。请定期备份，浏览器清理会丢失本地记录。</div>`)}${policyPanel()}</div>`;}
export function policyPanel(){return panel('政策依据与范围',`<div class="policylist"><a target="_blank" rel="noopener" href="https://shanghai.chinatax.gov.cn/zcfw/zcjd/201812/t443220.html">居民工资薪金累计预扣法及税率表 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/n810219/n810744/n3752930/n3752974/c3963364/content.html">依法确定的其他扣除法定类别 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/chinatax/n810341/n810765/n812146/n812300/c1079953/content.html">企业年金、职业年金个人缴费扣除口径 ↗</a><a target="_blank" rel="noopener" href="https://shenzhen.chinatax.gov.cn/sztax/zcwj/rdwd/202506/e9af4e54cabf47a2bf4e909f447e1af2.shtml">商业健康保险：每月200元、全年2400元限额 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c102416/c5211524/content.html">全年一次性奖金：符合条件可选单独计税或并入，执行至2027年12月31日 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c102416/c5237110/content.html">个人养老金：年度扣除限额12000元，未来领取另有税务规则 ↗</a><a target="_blank" rel="noopener" href="https://www.chinatax.gov.cn/chinatax/n810219/n810744/n3752930/n3752974/c3963375/content.html">专项附加扣除：资格、环节、额度与互斥条件 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c100012/c5213592/content.html">婴幼儿、子女教育及赡养老人扣除标准更新 ↗</a><a target="_blank" rel="noopener" href="https://fgk.chinatax.gov.cn/zcfgk/c100024/c5237602/content.html">大病医疗：超过15000元部分、年度限额80000元 ↗</a></div><p class="sub" style="margin-top:15px">支持2026、2027年度。政策核对日期2026-10-21。扣除未自动核验真实资格，输入需与凭证、家庭分配及税务记录一致。</p>`);}
